insert into settings(key, value, is_public) values ('site', '{"companyName":"SPP","legalName":"SPP Sole Co., Ltd","legalNameLo":"ບໍລິສັດ ເອັສພີພີ ຈຳກັດຜູ້ດຽວ","tagline":"Design it. Visualise it. Make it real.","description":"SPP is a Laos-based creative production company. From custom clothing and printed materials to signage, billboards and complete brand campaigns, we turn ideas into physical experiences.","foundedYear":2014,"address":{"line1":"Asian Road (T2), Nakham Village, Sikhottabong District","city":"Vientiane Capital","country":"Lao PDR","lat":17.9732,"lng":102.5886},"phone":"+8562055518882","landline":"+85621550226","whatsapp":"+8562055518882","email":"spp_sole@yahoo.com","hours":[{"days":"Monday – Friday","time":"08:30 – 17:30"},{"days":"Saturday","time":"08:30 – 12:00"}],"social":[{"platform":"facebook","url":"https://www.facebook.com/search/pages/?q=%E0%BA%9A%E0%BB%8D%E0%BA%A5%E0%BA%B4%E0%BA%AA%E0%BA%B1%E0%BA%94%20SPP%20%E0%BA%81%E0%BA%B2%E0%BA%99%E0%BA%9E%E0%BA%B4%E0%BA%A1%E0%BB%81%E0%BA%A5%E0%BA%B0%E0%BA%AA%E0%BA%B7%E0%BB%88%E0%BB%82%E0%BA%84%E0%BA%AA%E0%BA%B0%E0%BA%99%E0%BA%B2","handle":"ບໍລິສັດ SPP ການພິມແລະສື່ໂຄສະນາ"}],"logo":{"wordmark":null,"wordmarkOnPaper":null,"icon":null},"seo":{"titleTemplate":"%s — SPP","defaultTitle":"SPP — Custom Apparel, Printing & Billboard Advertising in Laos","defaultDescription":"Design, visualise and produce custom T-shirts, uniforms, printed materials, signage and billboard campaigns across Laos. Open SPP Studio and see your idea before it is made.","keywords":["custom t-shirt Laos","printing services Laos","clothing printing Vientiane","billboard advertising Vientiane","billboard rental Laos","promotional products Laos","custom uniforms Laos","signage Vientiane"]}}'::jsonb, true) on conflict (key) do update set value = excluded.value;
