insert into services(slug, name, verb, summary, body, deliverables, product_slugs, sort) values ('graphic-design', 'Graphic Design & Mockups', 'Design', 'Logos, artwork and print-ready files — made by people who know how it will be produced.', 'Design that ignores production gets rebuilt at the press. Ours starts from the garment, the substrate and the viewing distance, so what you approve is what gets made.', array['Logo & identity refinement','Apparel and merchandise artwork','Billboard & signage layouts','Print-ready file preparation','Photoreal mockups']::text[], array['custom-t-shirt','polo-shirt','poster']::text[], 1) on conflict (slug) do update set name = excluded.name, summary = excluded.summary, body = excluded.body, deliverables = excluded.deliverables, product_slugs = excluded.product_slugs;
insert into services(slug, name, verb, summary, body, deliverables, product_slugs, sort) values ('visualisation', 'SPP Studio & Visualisation', 'Visualise', 'See it on the shirt, on the street and on the billboard before a single metre is printed.', 'SPP Studio lets you build a front-and-back mockup in your browser, then place it in the real world. Approvals get faster because nobody has to imagine anything.', array['Online mockup designer','Front / back / sleeve previews','Billboard artwork preview','Watermarked downloads with Design ID']::text[], array['custom-t-shirt','polo-shirt','sports-cap','tote-bag','billboard-rental']::text[], 2) on conflict (slug) do update set name = excluded.name, summary = excluded.summary, body = excluded.body, deliverables = excluded.deliverables, product_slugs = excluded.product_slugs;
insert into services(slug, name, verb, summary, body, deliverables, product_slugs, sort) values ('production', 'Apparel & Print Production', 'Produce', 'Screen, DTF, sublimation, embroidery, offset and large-format under one roof.', 'One team owns the job from artwork check to quality control. Every order moves through the same tracked stages, so you always know where it is.', array['Garment manufacture & decoration','Promotional product sourcing','Offset & digital print','Large-format & signage fabrication','Quality control and packing']::text[], array['custom-t-shirt','polo-shirt','cup-print','vinyl-banner','led-signage']::text[], 3) on conflict (slug) do update set name = excluded.name, summary = excluded.summary, body = excluded.body, deliverables = excluded.deliverables, product_slugs = excluded.product_slugs;
insert into services(slug, name, verb, summary, body, deliverables, product_slugs, sort) values ('outdoor-advertising', 'Outdoor & Campaigns', 'Promote', 'Billboards, vehicles and events — planned as one campaign and measured with QR tracking.', 'A shirt, a banner and a billboard are stronger together. We plan the physical campaign as a system and attach QR tracking so you can see what the street sent you.', array['Billboard site planning & booking','Installation & maintenance','Vehicle branding','Event display systems','QR campaign tracking']::text[], array['billboard-rental','vehicle-wrap','j-flag','promo-counter']::text[], 4) on conflict (slug) do update set name = excluded.name, summary = excluded.summary, body = excluded.body, deliverables = excluded.deliverables, product_slugs = excluded.product_slugs;
insert into solutions(slug, goal, prompt, summary, recommend, bundle_slug, sort) values ('launch-a-business', 'Launch a Business', 'I''m opening something new.', 'Everything a new brand needs to look established on day one.', '[{"group":"Apparel","items":[{"label":"Staff polo shirts","product":"polo-shirt"},{"label":"Launch-day T-shirts","product":"custom-t-shirt"}]},{"group":"Print","items":[{"label":"Flyers & posters","product":"poster"},{"label":"Business cards & stationery","note":"Quoted with your print run"}]},{"group":"Display","items":[{"label":"A-board for the entrance","product":"a-board"},{"label":"Opening J-flags","product":"j-flag"}]},{"group":"Outdoor","items":[{"label":"Shopfront signage","product":"led-signage"}]}]'::jsonb, 'starter-brand-package', 1) on conflict (slug) do update set goal = excluded.goal, recommend = excluded.recommend;
insert into solutions(slug, goal, prompt, summary, recommend, bundle_slug, sort) values ('open-a-restaurant', 'Open a Restaurant', 'I''m opening a restaurant or café.', 'From the uniform to the cup in a customer''s hand to the sign they found you by.', '[{"group":"Apparel","items":[{"label":"Staff polos","product":"polo-shirt"},{"label":"Kitchen tees & aprons","product":"custom-t-shirt","note":"Aprons quoted on request"},{"label":"Caps","product":"sports-cap"}]},{"group":"Promotional","items":[{"label":"Printed cups & sleeves","product":"cup-print"},{"label":"Takeaway totes","product":"tote-bag"},{"label":"Terrace parasols","product":"umbrella"}]},{"group":"Print","items":[{"label":"Menus, posters & flyers","product":"poster"}]},{"group":"Outdoor","items":[{"label":"Illuminated shopfront sign","product":"led-signage"},{"label":"Neighbourhood billboard","product":"billboard-rental"},{"label":"Delivery vehicle branding","product":"vehicle-wrap"}]},{"group":"Digital","items":[{"label":"QR menu & campaign tracking","note":"Included with outdoor bookings"}]}]'::jsonb, 'restaurant-launch-package', 2) on conflict (slug) do update set goal = excluded.goal, recommend = excluded.recommend;
