insert into portfolio_projects(slug, title, client, sector, year, services, summary, is_sample, featured, palette, study, impact, sort, status) values ('sample-riverside-cafe-launch', 'A café that looked ten years old on day one', 'Riverside Café (sample)', 'Food & Beverage', 2026, array['Graphic Design','Apparel','Cup Printing','Signage','Billboard']::text[], 'Uniforms, cups, a lit shopfront and one well-placed billboard — planned as a single launch.', true, true, array['#1f5a3d','#e6dcc5','#ffd60a']::text[], '[{"heading":"The Client","body":"An independent café opening on a competitive riverside strip, with six staff and a four-week runway."},{"heading":"The Challenge","body":"New venues on the strip tend to look temporary for their first year: mismatched shirts, a vinyl banner for a sign, plain cups. The owner wanted to open looking permanent."},{"heading":"The Idea","body":"Treat the launch as one campaign rather than five purchases. One green, one typeface, one mark — on everything a customer touches or sees."},{"heading":"The Approach","body":"We started in SPP Studio with the owner in the room, building the polo front and back live. That approved mockup became the reference for every other item."},{"heading":"The Design","body":"A deep forest polo with cream chest embroidery; cream cups with a single-colour green print; a halo-lit fascia sign drawn to the building''s actual proportions."},{"heading":"The Production","body":"Embroidery, cup screen-printing and sign fabrication ran in parallel under one job number, each passing the same QC checklist before delivery."},{"heading":"The Result","body":"Everything arrived together, three days before opening. The billboard went live the same week with a QR code to the menu."},{"heading":"The Impact","body":"A sample of how the platform reports a campaign: scans, visits and enquiries attributed to each physical touchpoint."}]'::jsonb, '[{"value":"5","label":"product lines, one job number"},{"value":"4 wks","label":"brief to opening day"},{"value":"1","label":"approval round"}]'::jsonb, 0, 'published') on conflict (slug) do nothing;
insert into portfolio_projects(slug, title, client, sector, year, services, summary, is_sample, featured, palette, study, impact, sort, status) values ('sample-provincial-football-league', 'Twelve clubs, one kit system', 'Provincial Football League (sample)', 'Sport', 2026, array['Apparel','Sublimation','Event Display']::text[], 'A templated kit system so every club gets its own colours without starting from zero.', true, true, array['#2a35d6','#f5f5f2','#d4302b']::text[], '[{"heading":"The Client","body":"A regional league organising kit for twelve clubs and around three hundred players."},{"heading":"The Challenge","body":"Twelve separate design conversations, three hundred names and numbers, and one fixed kick-off date."},{"heading":"The Idea","body":"One Studio template, twelve colourways. Clubs pick colours and upload a crest; the structure stays consistent and production stays predictable."},{"heading":"The Approach","body":"Each club received a private design link. Approved designs flowed straight into quotes with player lists attached."},{"heading":"The Production","body":"All-over sublimation with individual names and numbers, batched by club and checked against the roster at QC."},{"heading":"The Result","body":"Kits delivered club by club ahead of the opening fixture, with re-order configurations saved for mid-season signings."}]'::jsonb, '[{"value":"12","label":"clubs on one template"},{"value":"300+","label":"personalised jerseys"},{"value":"0","label":"roster errors at QC"}]'::jsonb, 1, 'published') on conflict (slug) do nothing;
insert into portfolio_projects(slug, title, client, sector, year, services, summary, is_sample, featured, palette, study, impact, sort, status) values ('sample-telecom-highway-campaign', 'Five provinces, one message, measured', 'National Telecom Brand (sample)', 'Telecommunications', 2025, array['Billboard Network','Large-Format Print','QR Tracking']::text[], 'A multi-site billboard campaign with a different QR code on every face.', true, false, array['#ffd60a','#17171a','#00aeef']::text[], '[{"heading":"The Client","body":"A national brand launching a data package outside the capital."},{"heading":"The Challenge","body":"Outdoor advertising is usually bought on faith. The marketing team needed to show which sites earned their cost."},{"heading":"The Idea","body":"Give every billboard face its own tracked QR code, and report scans, visits and sign-ups per location."},{"heading":"The Approach","body":"Sites were shortlisted on the SPP Outdoor Network map, with artwork previewed on each structure before booking."},{"heading":"The Result","body":"A per-site performance table the client could use to renew the strongest locations and release the weakest."}]'::jsonb, '[{"value":"5","label":"provinces covered"},{"value":"8","label":"faces, individually tracked"},{"value":"Per-site","label":"response reporting"}]'::jsonb, 2, 'published') on conflict (slug) do nothing;
insert into faqs(topic, q, a, sort) select 'ordering', 'What is the minimum order?', 'It depends on the product and the print method. Most apparel starts at 12 pieces, caps at 12, totes at 50 and printed cups at 1,000. Signage, billboards and vehicle branding have no minimum. Each product page shows its own minimum.', 0 where not exists (select 1 from faqs where q = 'What is the minimum order?');
insert into faqs(topic, q, a, sort) select 'ordering', 'How do I get a price?', 'Where we can, the site shows an instant estimate that updates with your quantity and print choices. For everything else, send a quote request — it takes about a minute and arrives with your design attached. An estimate is a guide; your written quote from SPP is the price.', 1 where not exists (select 1 from faqs where q = 'How do I get a price?');
insert into faqs(topic, q, a, sort) select 'ordering', 'How long does production take?', 'Typical lead times are shown on each product. Most apparel is 5–14 working days from artwork approval. Rush production is often possible — tell us your date in the quote request.', 2 where not exists (select 1 from faqs where q = 'How long does production take?');
insert into faqs(topic, q, a, sort) select 'artwork', 'What artwork files do you need?', 'Vector files (AI, PDF, SVG, EPS) are ideal. For images, send the largest PNG or JPG you have. SPP Studio checks your upload and tells you if it looks too small for the print size — that check is advisory, and our team reviews every file before production.', 3 where not exists (select 1 from faqs where q = 'What artwork files do you need?');
insert into faqs(topic, q, a, sort) select 'artwork', 'I don''t have a logo or a design. Can you help?', 'Yes. Choose ''I need design help'' in any quote or project form, or book a consultation. Our designers work from a sketch, a reference, or just a conversation.', 4 where not exists (select 1 from faqs where q = 'I don''t have a logo or a design. Can you help?');
insert into faqs(topic, q, a, sort) select 'studio', 'Is the Studio mockup exactly what I will receive?', 'It is a close visual guide to placement, scale and colour. Screens and fabric show colour differently, so we confirm final colours and send a production proof for approval before anything is printed.', 5 where not exists (select 1 from faqs where q = 'Is the Studio mockup exactly what I will receive?');
insert into faqs(topic, q, a, sort) select 'studio', 'Why is there a watermark on my download?', 'Downloads are preview-resolution mockups stamped with your Design ID so our team can find your exact design instantly. Your original uploaded artwork stays private to your account.', 6 where not exists (select 1 from faqs where q = 'Why is there a watermark on my download?');
insert into faqs(topic, q, a, sort) select 'billboards', 'Does requesting a billboard confirm my booking?', 'No. A request holds nothing automatically. Our team checks availability for your dates and replies with a confirmation and contract. You will receive a booking reference immediately so you can follow up.', 7 where not exists (select 1 from faqs where q = 'Does requesting a billboard confirm my booking?');
insert into faqs(topic, q, a, sort) select 'billboards', 'What is included in the billboard price?', 'The guide price is the monthly site rental. Artwork design, printing and installation are quoted alongside it, and multi-site or long-term bookings are discounted.', 8 where not exists (select 1 from faqs where q = 'What is included in the billboard price?');
insert into faqs(topic, q, a, sort) select 'delivery', 'Do you deliver outside Vientiane?', 'Yes, we ship to every province. Delivery is quoted with your order. Signage and billboard installation is carried out by our own crews nationwide.', 9 where not exists (select 1 from faqs where q = 'Do you deliver outside Vientiane?');
insert into blog_posts(slug, title, excerpt, body, tag, read_mins, status, published_at) values ('screen-dtf-or-sublimation', 'Screen, DTF or sublimation? Choosing the right print for your shirts', 'Three print methods, three different strengths. A plain-language guide to which one your design actually needs.', 'Most customers ask for "printing". There are really three different processes behind that word, and picking the right one is the difference between a shirt that lasts and one that cracks by the rainy season.
insert into blog_posts(slug, title, excerpt, body, tag, read_mins, status, published_at) values ('billboard-artwork-that-works', 'Seven words or fewer: designing a billboard people can actually read', 'A driver gives your billboard about three seconds. Here is how to spend them.', 'A billboard is not a big flyer. It is read at speed, from a distance, by someone who is doing something else. The rules are different.
insert into blog_posts(slug, title, excerpt, body, tag, read_mins, status, published_at) values ('preparing-artwork-for-print', 'Preparing artwork for print: a five-minute checklist', 'Vector or pixel, RGB or CMYK, and why that logo from your website is probably too small.', 'Most production delays come from artwork, and most artwork problems are easy to avoid.
